func (this *StyledText) Insert(string_ string) {
	this.CheckWidget()
	if string_ == jrt.NullString {
		Error(ERROR_NULL_ARGUMENT)
	}
	if this.blockSelection {
		this.InsertBlockSelectionText(string_, false)
	} else {
		var sel *Point = this.GetSelectionRange()
		this.ReplaceTextRange(sel.X, sel.Y, string_)
	}
}
